#!/usr/bin/env node
import fs from 'node:fs';
import path from 'node:path';
import crypto from 'node:crypto';

console.log('\n⚡ ====================================================');
console.log('   EdgeKit Storage — Quick Setup Wizard');
console.log('====================================================\n');

const envPath = path.resolve(process.cwd(), '.dev.vars');

if (!fs.existsSync(envPath)) {
  const generatedKey = 'ek_' + crypto.randomBytes(24).toString('base64url');
  
  const defaultEnv = `# EdgeKit Storage - Local Configuration
# Automatically generated by setup wizard

API_KEY=${generatedKey}
PUBLIC_URL=http://localhost:8787/f
ALLOWED_MIME_TYPES=image/*,application/pdf
MAX_FILE_SIZE_MB=25
ENABLE_WORKER_FALLBACK_STREAM=true
ALLOWED_ORIGINS=http://localhost:3000,http://localhost:5173
`;

  fs.writeFileSync(envPath, defaultEnv, 'utf-8');
  console.log('✅ File .dev.vars created successfully!');
  console.log(`🔑 Your generated local API Key: ${generatedKey}\n`);
} else {
  console.log('ℹ️  File .dev.vars already exists. Preserving existing settings.\n');
}

console.log('--- Recommended Next Steps ---');
console.log('1. To run and test locally:');
console.log('   pnpm dev\n');
console.log('2. To deploy to Cloudflare:');
console.log('   a) Create the R2 bucket:');
console.log('      pnpm wrangler r2 bucket create cloudflare-storage-bucket');
console.log('   b) Set your production API Key:');
console.log('      pnpm wrangler secret put API_KEY');
console.log('   c) Deploy with 1 command:');
console.log('      pnpm deploy\n');
console.log('🚀 Done! Your serverless storage will be live with $0 egress bandwidth costs.\n');
